function shortestCompletingWord(licensePlate: string, words: string[]): string {
    const cnt: number[] = Array(26).fill(0);
    for (const c of licensePlate) {
        const i = c.toLowerCase().charCodeAt(0) - 97;
        if (0 <= i && i < 26) {
            ++cnt[i];
        }
    }
    let ans = '';
    for (const w of words) {
        if (ans.length && ans.length <= w.length) {
            continue;
        }
        const t = Array(26).fill(0);
        for (const c of w) {
            ++t[c.charCodeAt(0) - 97];
        }
        let ok = true;
        for (let i = 0; i < 26; ++i) {
            if (t[i] < cnt[i]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            ans = w;
        }
    }
    return ans;
}

impl Solution {
    pub fn shortest_completing_word(license_plate: String, words: Vec<String>) -> String {
        let mut cnt = vec![0; 26];
        for c in license_plate.chars() {
            if c.is_ascii_alphabetic() {
                cnt[((c.to_ascii_lowercase() as u8) - b'a') as usize] += 1;
            }
        }
        let mut ans = String::new();
        for w in words {
            if !ans.is_empty() && w.len() >= ans.len() {
                continue;
            }
            let mut t = vec![0; 26];
            for c in w.chars() {
                t[((c as u8) - b'a') as usize] += 1;
            }
            let mut ok = true;
            for i in 0..26 {
                if t[i] < cnt[i] {
                    ok = false;
                    break;
                }
            }
            if ok {
                ans = w;
            }
        }
        ans
    }
}

class Solution(object):
    def dominantIndex(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        if len(nums) == 1:
            return 0
        num1, num2, ind = -1, -1, -1
        for i, num in enumerate(nums):
            if num > num1:
                num1, num2, ind = num, num1, i
            elif num > num2:
                num2 = num
        if num1 >= 2 * num2:
            return ind
        else:
            return -1

class Solution(object):
    def shortestCompletingWord(self, licensePlate, words):
        """
        :type licensePlate: str
        :type words: List[str]
        :rtype: str
        """
        cnt = [0 for _ in range(26)]
        for c in licensePlate:
            if c.isalpha():
                cnt[ord(c.lower()) - ord('a')] += 1
        best_word = None
        for cur_word in words:
            cur_cnt = [0 for _ in range(26)]
            for c in cur_word:
                cur_cnt[ord(c) - ord('a')] += 1
            valid_flag = True
            for i in range(26):
                if cnt[i] > cur_cnt[i]:
                    valid_flag = False
                    break
            if not valid_flag:
                continue
            if not best_word or len(cur_word) < len(best_word):
                best_word = cur_word
        return best_word
